CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'customer',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_permissions(role VARCHAR(30) NOT NULL,permission VARCHAR(60) NOT NULL,PRIMARY KEY(role,permission));
CREATE TABLE IF NOT EXISTS login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bucket CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(bucket,created_at));
CREATE TABLE IF NOT EXISTS customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,account_number VARCHAR(40) NOT NULL UNIQUE,address VARCHAR(255) NOT NULL DEFAULT '',latitude DECIMAL(10,7),longitude DECIMAL(10,7),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS packages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,download_mbps INT UNSIGNED NOT NULL,upload_mbps INT UNSIGNED NOT NULL,price_cents BIGINT UNSIGNED NOT NULL,duration_days INT UNSIGNED NOT NULL,fair_usage TEXT,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS connections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,package_id BIGINT UNSIGNED NOT NULL,label VARCHAR(120) NOT NULL,address VARCHAR(255) NOT NULL,installation_status ENUM('requested','scheduled','completed','rejected') NOT NULL DEFAULT 'requested',desired_state ENUM('active','suspended') NOT NULL DEFAULT 'suspended',confirmed_state VARCHAR(40) NOT NULL DEFAULT 'unknown',state_version INT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(package_id) REFERENCES packages(id));
CREATE TABLE IF NOT EXISTS invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(60) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,connection_id BIGINT UNSIGNED NOT NULL,total_cents BIGINT UNSIGNED NOT NULL,paid_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,duration_days INT UNSIGNED NOT NULL,package_name VARCHAR(120) NOT NULL,status ENUM('open','partial','paid') NOT NULL DEFAULT 'open',due_at DATETIME NOT NULL,fulfilled_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(connection_id) REFERENCES connections(id));
CREATE TABLE IF NOT EXISTS invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL,quantity INT UNSIGNED NOT NULL,unit_cents BIGINT UNSIGNED NOT NULL,total_cents BIGINT UNSIGNED NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(100) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,amount_cents BIGINT UNSIGNED NOT NULL,method VARCHAR(30) NOT NULL,recorded_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(invoice_id) REFERENCES invoices(id),FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS allocations(payment_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,amount_cents BIGINT UNSIGNED NOT NULL,PRIMARY KEY(payment_id,invoice_id),FOREIGN KEY(payment_id) REFERENCES payments(id),FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE IF NOT EXISTS credits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,payment_id BIGINT UNSIGNED NOT NULL UNIQUE,amount_cents BIGINT UNSIGNED NOT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE IF NOT EXISTS subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL UNIQUE,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,price_cents BIGINT UNSIGNED NOT NULL,package_name VARCHAR(120) NOT NULL,FOREIGN KEY(connection_id) REFERENCES connections(id),FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE IF NOT EXISTS tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,priority ENUM('normal','high','urgent') NOT NULL DEFAULT 'normal',status ENUM('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS ticket_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,internal BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dedupe_key VARCHAR(190) NOT NULL UNIQUE,kind VARCHAR(30) NOT NULL,payload JSON NOT NULL,status ENUM('pending','processing','done','failed') NOT NULL DEFAULT 'pending',attempts INT UNSIGNED NOT NULL DEFAULT 0,available_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,locked_at DATETIME NULL,last_error VARCHAR(255),INDEX(status,available_at));
CREATE TABLE IF NOT EXISTS notification_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,message TEXT NOT NULL,delivery_mode VARCHAR(30) NOT NULL DEFAULT 'local_log',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id));
